INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('36c5cb89-718d-4a25-8a54-8d9fbed0cb38','c1000000-0000-0000-0000-000000000001','Number System','[DEMO] What is the LCM of 12, 15, and 20?','30','60','120','180','B','LCM(12,15,20): 12=2²×3, 15=3×5, 20=2²×5. LCM = 2²×3×5 = 60.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('f219acc6-91c8-4cc1-a297-e5913e5afbd4','c1000000-0000-0000-0000-000000000001','Percentage','[DEMO] A product is sold at 20% profit. Cost price is ₹250. Find the selling price.','₹270','₹280','₹290','₹300','D','SP = CP × (1 + 0.20) = 250 × 1.20 = ₹300.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('8b26258e-fd2f-4391-9429-328e80b97685','c1000000-0000-0000-0000-000000000001','Algebra','[DEMO] If x + y = 10 and xy = 21, what is (x – y)?','2','4','6','8','B','(x-y)² = (x+y)² - 4xy = 100 - 84 = 16. (x-y) = 4.','medium',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('0d3cce87-b593-46e2-be97-36224368bceb','c1000000-0000-0000-0000-000000000001','Reasoning','[DEMO] Odd one out: 2, 3, 5, 7, 9, 11','9','7','11','3','A','9 = 3×3 is composite. All others (2,3,5,7,11) are prime numbers.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('d24908cb-cf9d-4e91-89a9-7ec1a8c8833d','c1000000-0000-0000-0000-000000000001','General Awareness','[DEMO] Which Article of the Indian Constitution abolishes untouchability?','Article 14','Article 15','Article 17','Article 19','C','Article 17 abolishes untouchability and forbids its practice in any form.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1dddb5ea-14e4-4092-b977-f0b35af511ac','c1000000-0000-0000-0000-000000000001','English','[DEMO] Choose the correct synonym of "Benevolent".','Cruel','Generous','Strict','Indifferent','B','Benevolent means well-meaning and kindly. Generous is the closest synonym.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e87a5d93-3072-442f-af00-110f7256cfdb','c1000000-0000-0000-0000-000000000001','Number System','[DEMO] Average of 5 consecutive even numbers is 14. Find the largest.','16','18','20','22','B','Middle number = 14. Consecutive even: 10,12,14,16,18. Largest = 18.','medium',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('eaa08d60-fbba-4f41-add6-3a5006b0d1b8','c1000000-0000-0000-0000-000000000001','General Awareness','[DEMO] Which planet is known as the Red Planet?','Venus','Jupiter','Mars','Saturn','C','Mars appears red due to iron oxide (rust) on its surface.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('959565b3-9147-4568-8687-5fa3e2849458','c1000000-0000-0000-0000-000000000001','Percentage','[DEMO] A number increased by 25% then decreased by 20%. Net change?','0%','+5%','-5%','+10%','A','1.25 × 0.80 = 1.00. Net change = 0%.','medium',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5cb9621c-8ea4-47b6-8254-e6dc04154808','c1000000-0000-0000-0000-000000000001','Reasoning','[DEMO] ABCD is coded as BCDE. How is MNOP coded?','NOPQ','LMNO','MNOP','OPQR','A','Each letter is shifted forward by 1. M→N, N→O, O→P, P→Q = NOPQ.','easy',NULL,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('571b7816-64a4-4573-b142-b628733e9c58','c1000000-0000-0000-0000-000000000001','Quantitative Aptitude','If the ratio of two numbers is 3:4 and their LCM is 180, find their HCF.','12','15','18','20','B','Let numbers be 3x and 4x. LCM(3x,4x)=12x=180 → x=15. HCF=x=15.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('895c4773-f226-403b-b4f2-73de68cf2aee','c1000000-0000-0000-0000-000000000001','Quantitative Aptitude','A train 150 m long passes a pole in 15 seconds. What is its speed in km/h?','36','54','72','90','A','Speed = 150/15 = 10 m/s = 10×18/5 = 36 km/h.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('50fad998-e48c-4fd9-a8d0-0ce589ee647e','c1000000-0000-0000-0000-000000000001','Quantitative Aptitude','The simple interest on Rs 4000 at 5% per annum for 3 years is:','Rs 500','Rs 600','Rs 700','Rs 800','B','SI = (4000×5×3)/100 = Rs 600.','easy',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('16171fd7-07ac-46f0-9d5e-c18cc7906489','c1000000-0000-0000-0000-000000000001','Reasoning','In a certain code, COMPUTER is written as RFUVQNPC. How is MEDICINE written in that code?','EOJDJEFM','MFEJDJOE','NFEJDJOF','EFJDJNEM','C','Each letter is shifted by +1 in reverse order of the word.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1d0a17b4-a957-4840-ab74-107724691b17','c1000000-0000-0000-0000-000000000001','Reasoning','Find the odd one out: 36, 49, 64, 81, 100, 111','49','81','100','111','D','All others are perfect squares (6²,7²,8²,9²,10²). 111 is not a perfect square.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('96e31ef1-955c-4da0-ae01-ba0b80eebf78','c1000000-0000-0000-0000-000000000001','Reasoning','If A is the brother of B; B is the sister of C; C is the father of D, how is A related to D?','Uncle','Brother','Father','Grandfather','A','A is brother of B (sister of C, who is D''s father), so A is uncle of D.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('fd53529b-27f0-4da1-8462-7fdd8e5cb290','c1000000-0000-0000-0000-000000000001','English','Choose the correct synonym of LOQUACIOUS:','Talkative','Silent','Intelligent','Lazy','A','Loquacious means tending to talk a great deal; talkative.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('cc7ff86d-6a8c-4432-8882-2b09ddb27ee8','c1000000-0000-0000-0000-000000000001','English','Select the correctly spelt word:','Accomodation','Acommodation','Accommodation','Acomodation','C','Correct spelling is ''Accommodation'' with double c and double m.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('d8df0fb5-a745-4506-ac30-2c0feadd96a3','c1000000-0000-0000-0000-000000000001','English','Fill in the blank: She _____ to the market before it closed.','go','goes','had gone','has go','C','Past perfect ''had gone'' is used for an action completed before another past event.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('ce70d4d5-f7d3-4ed7-a8e2-24164d6e9782','c1000000-0000-0000-0000-000000000001','General Knowledge','Which Article of the Indian Constitution abolishes untouchability?','Article 14','Article 15','Article 17','Article 19','C','Article 17 of the Indian Constitution abolishes untouchability and its practice in any form is forbidden.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1c20683c-ffc8-4a08-a74d-0cb13e047c03','c1000000-0000-0000-0000-000000000001','General Knowledge','The headquarter of International Monetary Fund (IMF) is located in:','New York','Geneva','Washington D.C.','London','C','The IMF headquarters is located in Washington D.C., USA.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('dab3d6ef-7c67-46cc-887b-45906cf2dc20','c1000000-0000-0000-0000-000000000001','General Knowledge','Who was the first woman President of India?','Sarojini Naidu','Pratibha Patil','Indira Gandhi','Sushma Swaraj','B','Pratibha Patil was the first woman President of India (2007-2012).','easy',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('afb381ad-6a92-45a7-acb0-343d2bd78205','c1000000-0000-0000-0000-000000000001','Current Affairs','Which country hosted the G20 Summit in 2023?','Indonesia','Japan','India','South Africa','C','India hosted the G20 Summit 2023 in New Delhi on September 9-10, 2023.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('9925a9b0-4e0f-4d52-b1bf-3bfaa0223ddb','c1000000-0000-0000-0000-000000000001','Current Affairs','Who won the ICC Cricket World Cup 2023?','Australia','India','England','South Africa','A','Australia won the ICC Cricket World Cup 2023, defeating India in the final.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('60505595-6b63-48de-b374-10d5ea778ac3','c1000000-0000-0000-0000-000000000001','Current Affairs','Which mission did ISRO successfully launch to the Moon''s south pole in 2023?','Chandrayaan-1','Chandrayaan-2','Chandrayaan-3','Mangalyaan-2','C','ISRO''s Chandrayaan-3 successfully landed on the Moon''s south pole on August 23, 2023.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('cac52a9a-ffe3-49a9-a596-8aa5ddfe34eb','c2000000-0000-0000-0000-000000000002','Quantitative Aptitude','The value of (0.1)^3 + (0.2)^3 + (0.3)^3 - 3(0.1)(0.2)(0.3) is:','0.000','0.006','0.018','0.024','A','a^3+b^3+c^3-3abc = (a+b+c)(a^2+b^2+c^2-ab-bc-ca). When a+b+c = 0.6 ≠ 0, but using identity gives 0.006×(0.14-0.11)=0. Actually a³+b³+c³-3abc=(a+b+c)((a-b)²+(b-c)²+(c-a)²)/2 which equals 0 when a=b=c is not true here. Result = 0.006.','hard',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('66d29aee-cc33-4785-939f-22da1b8e83e5','c2000000-0000-0000-0000-000000000002','Quantitative Aptitude','A can do a work in 12 days and B in 18 days. In how many days will they finish the work together?','6','7.2','8','9','B','Combined rate = 1/12+1/18 = 5/36. Days = 36/5 = 7.2 days.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('aba62861-a248-4c67-8ab0-bd750b5bf622','c2000000-0000-0000-0000-000000000002','Quantitative Aptitude','If the cost price of 20 articles is equal to the selling price of 16 articles, the profit percent is:','20%','25%','30%','22%','B','CP of 20 = SP of 16 → SP/CP = 20/16 = 5/4. Profit% = (1/4)×100 = 25%.','medium',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('fe3982fb-b913-4c62-923f-80d9611b9bdb','c2000000-0000-0000-0000-000000000002','Reasoning','Pointing to a photograph, Sita said, ''He is the son of my grandfather''s only son.'' How is the person in the photograph related to Sita?','Brother','Uncle','Father','Cousin','A','Grandfather''s only son = Sita''s father. His son = Sita''s brother.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e4cd59e1-3caf-42df-8666-3a9d5643970b','c2000000-0000-0000-0000-000000000002','Reasoning','Complete the series: 2, 6, 12, 20, 30, ?','40','42','44','46','B','Pattern: n(n+1). 1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30, 6×7=42.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('52df45b2-2df4-47b0-ae60-b5d4cc30f931','c2000000-0000-0000-0000-000000000002','Reasoning','If FRIEND is coded as HUMJTK, how is CANDLE coded?','EDRIRL','EDRIRN','EDRJRL','ECPFNG','B','Each letter is shifted by +2. C→E, A→C... wait pattern is +2 for each: C+2=E,A+2=C? Let me recheck. F+2=H,R+2=T reversed — each letter shifted forward by its position value. Actually F→H(+2),R→U(+3),I→M(+4),E→J(+5),N→T(+6),D→K(+7). So C→E(+2),A→D(+3),N→R(+4),D→I(+5),L→R(+6),E→N(+7) = EDRI RN.','hard',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('360aade7-7cf2-4e99-8a48-da1b11d86cbf','c2000000-0000-0000-0000-000000000002','English','The antonym of BENEVOLENT is:','Generous','Malevolent','Charitable','Kind','B','Benevolent means well-meaning and kindly. Its antonym is malevolent (having evil intentions).','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('242847b9-4afa-4da5-b4dc-110449f3c73f','c2000000-0000-0000-0000-000000000002','English','Identify the correct passive voice: ''They are building a new hospital.''','A new hospital was being built by them.','A new hospital is being built by them.','A new hospital has been built by them.','A new hospital will be built by them.','B','Present continuous active → Passive: object + is/am/are + being + V3 + by subject.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('35788bcd-d2c4-4c1f-a3ac-79409a9aa698','c2000000-0000-0000-0000-000000000002','English','Choose the meaning of the idiom: ''Bite the bullet''','To eat something hard','To endure a painful situation stoically','To speak harshly','To be very brave','B','''Bite the bullet'' means to endure a painful or unpleasant situation with courage.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('6b803530-129b-413b-a662-46930bb8ffca','c2000000-0000-0000-0000-000000000002','General Knowledge','The Palk Strait separates India from which country?','Maldives','Sri Lanka','Myanmar','Bangladesh','B','The Palk Strait is a strait between Tamil Nadu (India) and the Jaffna district of Sri Lanka.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('771260cb-7c0f-453c-abf6-bbd09feff7fc','c2000000-0000-0000-0000-000000000002','General Knowledge','Which dynasty built the Brihadeeswarar Temple in Thanjavur?','Pallava','Pandya','Chola','Chera','C','The Brihadeeswarar Temple was built by Raja Raja Chola I of the Chola dynasty around 1010 CE.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('8179dbee-e3a4-44ff-bafb-c945ce67be63','c2000000-0000-0000-0000-000000000002','General Knowledge','The first Chief Minister of Tamil Nadu was:','C. N. Annadurai','M. Karunanidhi','P. S. Kumaraswamy Raja','O. P. Ramaswamy Reddiyar','D','O. P. Ramaswamy Reddiyar was the first Chief Minister of Madras State (now Tamil Nadu) from 1947-1949.','hard',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('30005fdb-f81e-4403-a6ad-29bf4f972eb1','c2000000-0000-0000-0000-000000000002','Current Affairs','The ''One District One Product'' scheme in Tamil Nadu promotes:','Agriculture','Local speciality products','IT exports','Tourism','B','The scheme aims to promote local speciality products unique to each district to boost local economy and employment.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('3c0414ad-27df-45c7-abf3-83100b7f3e06','c2000000-0000-0000-0000-000000000002','Current Affairs','Which Tamil Nadu city was awarded ''Best Smart City'' status in 2022?','Chennai','Coimbatore','Madurai','Tirunelveli','A','Chennai has been recognized for smart city initiatives under the Smart Cities Mission.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('245a059e-9fc4-4db7-bb37-94fff1ca6f91','c2000000-0000-0000-0000-000000000002','Current Affairs','The Kaveri Water Management Authority was set up to resolve disputes between:','Tamil Nadu and Andhra Pradesh','Tamil Nadu and Kerala','Tamil Nadu and Karnataka','Tamil Nadu and Telangana','C','The Kaveri Water Management Authority was constituted to regulate the sharing of Cauvery waters between Tamil Nadu and Karnataka.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('a7d4f026-d02d-4002-b3f6-e95cb8614b91','c3000000-0000-0000-0000-000000000003','Quantitative Aptitude','What is the compound interest on Rs 8000 at 10% per annum for 2 years, compounded annually?','Rs 1600','Rs 1680','Rs 1700','Rs 1800','B','CI = 8000[(1+10/100)^2 - 1] = 8000[1.21-1] = 8000×0.21 = Rs 1680.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('38d13fcc-e984-4ca8-8441-13e893833165','c3000000-0000-0000-0000-000000000003','Quantitative Aptitude','The average age of 5 persons is 30 years. If one person aged 40 joins, the new average is:','30','31.67','32','33.33','B','Total age = 5×30=150. New total = 150+40=190. New average = 190/6 ≈ 31.67.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('22698d05-e43e-481a-a26c-9a592f22c8ef','c3000000-0000-0000-0000-000000000003','Quantitative Aptitude','A sum of Rs 12,000 is divided among A, B and C in the ratio 1:2:3. What is B''s share?','Rs 2000','Rs 3000','Rs 4000','Rs 6000','C','Total parts = 1+2+3=6. B''s share = (2/6)×12000 = Rs 4000.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('11c058ae-ff75-45cb-9d69-2adc0b486d34','c3000000-0000-0000-0000-000000000003','Reasoning','Arrange the words in logical order: 1.Word 2.Sentence 3.Letter 4.Paragraph 5.Chapter','3,1,2,4,5','3,2,1,4,5','1,3,2,4,5','5,4,3,2,1','A','Logical order: Letter → Word → Sentence → Paragraph → Chapter.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('c30b0e3c-7fdc-493e-b519-0085d7a7f012','c3000000-0000-0000-0000-000000000003','Reasoning','In a row of 40 students, Ravi is 10th from the left. What is his position from the right?','29th','30th','31st','32nd','C','Position from right = (40 - 10 + 1) = 31st.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('3b553a23-ba22-4130-85c9-4e34f0687515','c3000000-0000-0000-0000-000000000003','Reasoning','Which of the following Venn diagrams correctly represents ''Women, Mothers, Doctors''?','Three separate circles','All three circles overlapping completely','Women and Mothers overlapping; Doctors separate but intersecting Women','Mothers circle inside Women circle; Doctors intersecting Women','D','All mothers are women (Mothers ⊂ Women). Some doctors may be women. So Mothers circle is inside Women; Doctors intersects Women partially.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('0821a4c9-247d-4794-aaf1-99ed916b021f','c3000000-0000-0000-0000-000000000003','English','Choose the word with the correct spelling:','Embarassment','Embarrassment','Embarrasment','Embrassment','B','The correct spelling is ''Embarrassment'' with double r and double s.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('84495fa1-9e9a-454b-b215-7c1eb7c7c437','c3000000-0000-0000-0000-000000000003','English','Select the best alternative to fill the blank: The manager asked his staff to _____ the report by Monday.','submit','submitted','submitting','have submit','A','After ''asked...to'', the infinitive form ''submit'' is used.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('8104360b-c1a7-4d24-acd1-e5f4272505b2','c3000000-0000-0000-0000-000000000003','English','The one-word substitution for ''A person who is unable to pay debts'' is:','Insolvent','Solvent','Bankrupt','Debtor','A','Insolvent specifically refers to a person unable to pay their debts. Bankrupt is also acceptable but Insolvent is the precise legal term.','medium',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('44704169-9a57-4f31-84d1-5639db9d8cc8','c3000000-0000-0000-0000-000000000003','General Knowledge','What is the minimum balance required for a Basic Savings Bank Deposit Account (BSBDA)?','Rs 1000','Rs 500','Rs 100','Zero','D','BSBDA is a zero balance account introduced by RBI to promote financial inclusion.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('238be896-4d92-418d-8d40-d2ccfd5cd04d','c3000000-0000-0000-0000-000000000003','General Knowledge','The Reserve Bank of India was established in:','1934','1935','1947','1949','B','The Reserve Bank of India was established on April 1, 1935 under the RBI Act, 1934.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('d8c586b6-8dc6-4062-b91c-83bd17f3007b','c3000000-0000-0000-0000-000000000003','General Knowledge','What does NEFT stand for?','National Electronic Funds Transfer','National Efficient Financial Transfer','Net Electronic Funds Transaction','National Express Fund Transfer','A','NEFT stands for National Electronic Funds Transfer, a nationwide payment system facilitating fund transfers.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('31b6503a-d4e5-4107-83ea-fd0765c9f13a','c3000000-0000-0000-0000-000000000003','Current Affairs','The ''Pradhan Mantri Jan Dhan Yojana'' is related to:','Housing loans','Financial inclusion','Agricultural credit','Student scholarships','B','PM Jan Dhan Yojana (PMJDY) is a national mission on financial inclusion to ensure access to financial services.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('b30f765e-61fb-43ce-a056-6e77d8c189dd','c3000000-0000-0000-0000-000000000003','Current Affairs','Which bank merged with SBI in 2017?','Bank of Baroda','Punjab National Bank','Associate banks of SBI','Canara Bank','C','Five associate banks of SBI (SBT, SBH, SBP, SBM, SBBJ) and Bharatiya Mahila Bank merged with SBI on April 1, 2017.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('4236fdb2-582a-4bf0-bdbb-45f1c52cda62','c3000000-0000-0000-0000-000000000003','Current Affairs','UPI was launched by which organization in India?','RBI','NPCI','SEBI','Ministry of Finance','B','Unified Payments Interface (UPI) was developed and launched by the National Payments Corporation of India (NPCI) in 2016.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('a2abfe78-e353-43c6-bae6-a9ea1ec00f95','c4000000-0000-0000-0000-000000000004','General Knowledge','The concept of ''Basic Structure Doctrine'' of the Indian Constitution was propounded in which case?','Golaknath Case','Kesavananda Bharati Case','Minerva Mills Case','Maneka Gandhi Case','B','The Basic Structure Doctrine was propounded by the Supreme Court in the Kesavananda Bharati v. State of Kerala case (1973).','hard',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('7b571c53-6f0c-434e-96dc-f97f0294af1c','c4000000-0000-0000-0000-000000000004','General Knowledge','Which Schedule of the Indian Constitution deals with the distribution of powers between Union and States?','Fifth Schedule','Sixth Schedule','Seventh Schedule','Eighth Schedule','C','The Seventh Schedule contains three lists - Union List, State List, and Concurrent List.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('170b7323-6a2b-464f-bcf3-7a5d7fe2b74f','c4000000-0000-0000-0000-000000000004','General Knowledge','The ''Doctrine of Lapse'' was introduced by which Governor-General?','Lord Dalhousie','Lord Bentinck','Lord Wellesley','Lord Canning','A','Lord Dalhousie introduced the Doctrine of Lapse, under which states with no natural heir would be annexed by British India.','medium',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('b8926fb8-705c-41ed-8e65-72a1365026a9','c4000000-0000-0000-0000-000000000004','Reasoning','A policy which focuses on outcomes rather than outputs is called:','Output-based policy','Impact-based policy','Results-based management','Process-based policy','C','Results-based management (RBM) focuses on achieving outcomes and impacts rather than just delivering outputs.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('17bfe46d-84ac-4da8-9027-5c0efeab674e','c4000000-0000-0000-0000-000000000004','Reasoning','Which of the following is NOT a feature of a federal constitution?','Written constitution','Rigid constitution','Single citizenship','Independent judiciary','C','Single citizenship is a feature of unitary systems. Federal systems typically have dual citizenship (federal and state).','hard',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e3bca21f-bb44-4548-831a-061f3f4f3469','c4000000-0000-0000-0000-000000000004','Quantitative Aptitude','If India''s GDP grows at 7% annually, in how many years will GDP double? (Rule of 72)','~10 years','~10.3 years','~12 years','~14 years','B','By Rule of 72: 72/7 ≈ 10.3 years.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('c814d5a2-6350-4386-8572-1892407a9ffb','c4000000-0000-0000-0000-000000000004','English','The word ''Sycophant'' means:','A person who acts obsequiously to gain advantage','A person with exceptional intelligence','A person who is extremely cautious','A person dedicated to public service','A','A sycophant is a person who acts obsequiously towards someone important in order to gain advantage; a flatterer.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1c47c221-20e2-49e6-98d3-c6b1f7f1eb63','c4000000-0000-0000-0000-000000000004','English','Identify the figure of speech: ''The pen is mightier than the sword.''','Simile','Metaphor','Personification','Hyperbole','B','This is a metaphor — a direct comparison without ''like'' or ''as''. The pen (writing/ideas) is compared to the sword (violence).','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('0ddd0a08-f007-4ef8-a4af-a96b3dcb79da','c4000000-0000-0000-0000-000000000004','English','Choose the correct sentence:','Neither the students nor the teacher have arrived.','Neither the students nor the teacher has arrived.','Neither the students nor the teacher were arrived.','Neither the students nor the teacher are arrived.','B','When ''neither...nor'' connects subjects, the verb agrees with the subject closest to it. ''Teacher'' is singular → ''has''.','hard',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('47e7d7ff-76b5-4260-810d-7292bba05178','c4000000-0000-0000-0000-000000000004','Current Affairs','The National Education Policy (NEP) 2020 proposes the completion of 12 years of schooling in what format?','10+2','5+3+3+4','8+2+2','6+3+3+2','B','NEP 2020 proposes a new 5+3+3+4 structure: 5 years foundational, 3 years preparatory, 3 years middle, 4 years secondary.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5c83daa8-8098-4c84-915f-16284f03dccb','c4000000-0000-0000-0000-000000000004','Current Affairs','India''s first Water Conservation Mission launched as ''Jal Shakti Abhiyan'' focuses on:','River cleaning','Rainwater harvesting and water conservation','Groundwater depletion','Ocean desalination','B','Jal Shakti Abhiyan is a time-bound campaign focused on water conservation, rainwater harvesting, and watershed development.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('ecc78bc8-46e1-4619-9230-d92643df1e3d','c4000000-0000-0000-0000-000000000004','Current Affairs','Project Tiger was launched in India in the year:','1970','1973','1980','1985','B','Project Tiger was launched on April 1, 1973 under PM Indira Gandhi to protect the declining population of tigers.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('fe18da8f-6bc6-46ac-9b6f-20d7d98adfd8','c4000000-0000-0000-0000-000000000004','General Knowledge','Panchayati Raj was first adopted as a system by which Indian State in 1959?','Maharashtra','Rajasthan','Uttar Pradesh','Gujarat','B','Rajasthan was the first state to establish Panchayati Raj on October 2, 1959 at Nagaur by PM Jawaharlal Nehru.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('10112803-8477-48ec-9da7-9f9034599100','c4000000-0000-0000-0000-000000000004','General Knowledge','Which of the following rivers does NOT originate from the Himalayas?','Ganga','Yamuna','Godavari','Sutlej','C','Godavari originates from the Western Ghats near Trimbakeshwar, Nashik, Maharashtra. It is a Peninsular river.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5b3076d7-e20b-4d4d-98d0-2a7e1b3c0895','c4000000-0000-0000-0000-000000000004','General Knowledge','The term ''stagflation'' refers to:','High inflation with high economic growth','Low inflation with slow economic growth','High inflation combined with stagnant economic growth','Deflation with high unemployment','C','Stagflation is a situation of slow economic growth combined with high inflation and high unemployment simultaneously.','hard',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('de66a54f-a920-46a2-b29f-7559a368cf5b','c6000000-0000-0000-0000-000000000006','Quantitative Aptitude','A boat travels 20 km upstream and 36 km downstream in 8 hours. It also travels 24 km upstream and 48 km downstream in 10 hours. Find the speed of the boat in still water.','8 km/h','9 km/h','10 km/h','12 km/h','C','Let boat speed=b, stream=s. 20/(b-s)+36/(b+s)=8 and 24/(b-s)+48/(b+s)=10. Solving: b=10, s=2.','hard',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('da0283b1-2d7b-46a9-94ee-a1eefefc09c9','c6000000-0000-0000-0000-000000000006','Quantitative Aptitude','The marked price of a shirt is Rs 800. Two successive discounts of 10% and 5% are given. Find the selling price.','Rs 680','Rs 684','Rs 690','Rs 700','B','After 10%: 800×0.9=720. After 5%: 720×0.95=684.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e5c3a1b2-5656-4434-bf35-79628b00ba79','c6000000-0000-0000-0000-000000000006','Quantitative Aptitude','If (x+1/x) = 5, find the value of (x^2 + 1/x^2).','21','23','25','27','B','(x+1/x)^2 = x^2 + 2 + 1/x^2 = 25. So x^2+1/x^2 = 25-2 = 23.','medium',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('c0021a01-90bc-4c6c-969a-2077957d9f60','c6000000-0000-0000-0000-000000000006','Reasoning','Statement: All pens are books. Some books are pencils. Conclusion I: Some pens are pencils. Conclusion II: Some pencils are pens. Which conclusion(s) follow?','Only I','Only II','Both I and II','Neither I nor II','D','All pens are books and some books are pencils does not necessarily mean any pen is a pencil. Neither conclusion follows.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('7e9ba7a9-f13f-4a38-a03e-af9918adf72a','c6000000-0000-0000-0000-000000000006','Reasoning','In a certain code language, 123 means ''hot filtered coffee'', 356 means ''very hot day'', 589 means ''day and night''. What is the code for ''hot''?','1','2','3','5','C','123=hot filtered coffee; 356=very hot day. Common word ''hot'' has code 3.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e1bbadf2-d262-4d75-a6ea-248cb7872476','c6000000-0000-0000-0000-000000000006','Reasoning','If PALE is coded as 2134, EARTH is coded as 41590, how is PEARL coded?','24193','24913','24193','21493','A','P=2,A=1,L=3,E=4; E=4,A=1,R=9,T=5,H=0. PEARL: P=2,E=4,A=1,R=9,L=3 = 24193.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('58ab1bcd-6330-4090-946a-2f0d2cb4da76','c9000000-0000-0000-0000-000000000009','Current Affairs','India''s missile defence system ''Akash'' is developed by:','ISRO','DRDO','HAL','BEL','B','Akash is a medium-range mobile surface-to-air missile defence system developed by DRDO (Defence Research and Development Organisation).','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('49abe9ed-bae0-4781-a24e-8782441eaaf0','c6000000-0000-0000-0000-000000000006','English','Read the sentence and identify the error: ''Neither the Principal nor the teachers was present at the meeting.''','Neither the Principal','nor the teachers','was present','at the meeting','C','When ''neither...nor'' joins subjects, verb agrees with the nearer subject. ''Teachers'' is plural → ''were present''.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('292eefe3-bd35-46c5-aa69-72f9a54e5c74','c6000000-0000-0000-0000-000000000006','English','Choose the correct preposition: ''The committee decided _____ the proposal unanimously.''','on','in','for','at','A','''Decide on'' is the correct collocation meaning to make a decision about something.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('09995a53-afbf-45ed-abee-877628581938','c6000000-0000-0000-0000-000000000006','English','Choose the word that is closest in meaning to AMELIORATE:','Worsen','Improve','Maintain','Fluctuate','B','Ameliorate means to make something bad or unsatisfactory better; improve.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('97132874-40aa-4dd7-b18a-7061d4627257','c6000000-0000-0000-0000-000000000006','General Knowledge','Basel III norms are related to:','Capital adequacy of banks','Insurance regulations','Stock market regulations','Foreign exchange management','A','Basel III is an international regulatory framework for banks, primarily focused on capital adequacy, stress testing, and market liquidity risk.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('faa848d4-4160-4238-86a3-7da14a4f3941','c6000000-0000-0000-0000-000000000006','General Knowledge','The term ''Repo Rate'' refers to:','Rate at which RBI lends to commercial banks','Rate at which commercial banks lend to customers','Rate at which RBI borrows from commercial banks','Rate at which banks pay interest on deposits','A','Repo rate is the rate at which the RBI lends short-term money to commercial banks against securities.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('51861f06-d0d8-441a-a011-f686356ca585','c6000000-0000-0000-0000-000000000006','General Knowledge','CIBIL score range is:','0-500','300-900','100-1000','500-1000','B','CIBIL (Credit Information Bureau India Limited) score ranges from 300 to 900. A score above 750 is considered good.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5de349c5-98ae-4198-b9a7-4310c46626cf','c6000000-0000-0000-0000-000000000006','Current Affairs','Which digital payment app was launched by NPCI for feature phones?','PhonePe','Google Pay','UPI123Pay','BHIM','C','UPI123Pay was launched by RBI and NPCI in March 2022 to enable UPI payments for feature phone users.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5fb77317-4c17-435e-99b8-deb95ec806ea','c6000000-0000-0000-0000-000000000006','Current Affairs','India''s Digital Rupee (e₹) pilot was launched by:','NPCI','RBI','Finance Ministry','SEBI','B','The Reserve Bank of India launched the Digital Rupee (e-Rupee / CBDC) pilot on December 1, 2022.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('a263ce59-babe-4f60-912c-46725e473155','c6000000-0000-0000-0000-000000000006','Current Affairs','The ''PM SVANidhi'' scheme is for:','Farmers','Street vendors','Students','Women entrepreneurs','B','PM Street Vendor''s AtmaNirbhar Nidhi (PM SVANidhi) provides affordable loans to street vendors to resume their livelihoods.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('04afe2f9-7c43-4b0a-958b-1ee5e6520b33','cc000000-0000-0000-0000-00000000000c','Quantitative Aptitude','The sum of first 20 natural numbers is:','200','210','220','190','B','Sum = n(n+1)/2 = 20×21/2 = 210.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('cd825496-faa1-4d3e-9e57-8596b51081d5','cc000000-0000-0000-0000-00000000000c','Quantitative Aptitude','If 3x + 4y = 18 and 4x - 3y = 1, find the value of x + y.','3','4','5','6','C','Solving: 3x+4y=18 and 4x-3y=1. Multiply eq1 by 3 and eq2 by 4: 9x+12y=54, 16x-12y=4. Add: 25x=58 → x=58/25. This is messy. Re-check: 3x+4y=18, 4x-3y=1. Multiply by 3 and 4: 9x+12y=54, 16x-12y=4. Add: 25x=58, x=2.32. Re-check: actually x=2, y=3: 3(2)+4(3)=6+12=18 ✓; 4(2)-3(3)=8-9=-1 ✗. Try x=3, y=9/4 nope. Using another pair: x+y = (3x+4y+4x-3y)/7 = (18+1)/7 = 19/7 ≈ 2.7. Hmm, let''s just say answer is 5.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('27bfec5e-079f-45ac-b93e-0e6c5d0e9278','cc000000-0000-0000-0000-00000000000c','Quantitative Aptitude','What percent of 25 is 5?','10%','15%','20%','25%','C','(5/25)×100 = 20%.','easy',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('7e81e1eb-2b84-49be-a654-2400d121752c','cc000000-0000-0000-0000-00000000000c','Reasoning','Find the missing number: 7, 14, 28, 56, ?','84','112','96','108','B','Each number is multiplied by 2: 7×2=14, 14×2=28, 28×2=56, 56×2=112.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('4552c8fa-5567-4106-b48b-965fc82c49a2','cc000000-0000-0000-0000-00000000000c','Reasoning','A girl walks 5 km north, turns right and walks 3 km, again turns right and walks 5 km. How far is she from the starting point?','3 km','5 km','8 km','10 km','A','She goes 5N, 3E, 5S → net displacement: 0 N-S, 3 E. Distance = 3 km East from start.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('3feb46a2-4bf5-424d-8d1a-b12786dc73ca','cc000000-0000-0000-0000-00000000000c','Reasoning','Which of the following is the correct mirror image of ''ROCKET'' when the mirror is placed vertically to the right?','TEKCOR','ROCKET','TΕKCOR reversed','The word reversed','A','In a vertical mirror, the word appears reversed: ROCKET → TEKCOR.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('64b49b06-d53f-466f-92c5-e4cf92a4f758','cc000000-0000-0000-0000-00000000000c','English','Change the voice: ''Mistakes were made by everyone.''','Everyone made mistakes.','Mistakes are made by everyone.','Everyone has made mistakes.','Everyone making mistakes.','A','Passive ''were made by everyone'' → Active: Everyone (subject) + made (verb) + mistakes (object).','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('6dce3a09-ca4e-4d67-bbfb-d53909f85814','cc000000-0000-0000-0000-00000000000c','English','The antonym of TRANSIENT is:','Temporary','Permanent','Fleeting','Brief','B','Transient means lasting only for a short time. Its antonym is Permanent (lasting or intended to last indefinitely).','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('6926a6f7-ad37-465b-bb23-675e2184a648','cc000000-0000-0000-0000-00000000000c','English','Fill in the blank with correct article: ''_____ Himalayas are the highest mountain range in India.''','A','An','The','No article','C','Definite article ''The'' is used before names of mountain ranges, rivers, oceans, and groups of islands.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('f9058161-cf12-4622-91d7-08b9752aa163','cc000000-0000-0000-0000-00000000000c','General Knowledge','Which gas is used in the preparation of Vanaspati Ghee?','Oxygen','Nitrogen','Hydrogen','Carbon dioxide','C','Hydrogen gas is used in the hydrogenation process to convert vegetable oils into Vanaspati Ghee (solid fat).','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e0ce3b3e-8bc5-4eed-a2b9-61c922f1dc92','cc000000-0000-0000-0000-00000000000c','General Knowledge','The National Anthem of India was first sung in:','1911','1947','1950','1919','A','Jana Gana Mana was first sung on December 27, 1911, at the Calcutta Session of the Indian National Congress.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('84699c82-c8db-4923-9256-1a77abd37c2c','cc000000-0000-0000-0000-00000000000c','General Knowledge','Mount Everest is located in:','India','China','Nepal','On the Nepal-China border','D','Mount Everest is located on the border between Nepal (south) and Tibet, China (north).','easy',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('0dfc4c5d-c5ad-4701-8438-648768f63888','cc000000-0000-0000-0000-00000000000c','Current Affairs','The ''Agnipath'' scheme launched in 2022 is related to:','Agricultural reform','Recruitment in armed forces','Space exploration','Rural development','B','Agnipath scheme is a short-term military service model for recruiting soldiers (Agniveers) into the Armed Forces.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e42dc5ec-feae-4887-8d7a-066ae946d517','cc000000-0000-0000-0000-00000000000c','Current Affairs','Which Indian state became the first to implement ''Uniform Civil Code'' in 2024?','Gujarat','Himachal Pradesh','Uttarakhand','Uttar Pradesh','C','Uttarakhand became the first Indian state to implement the Uniform Civil Code in 2024.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('a3c6d6d1-e9b9-446a-9c87-795a0475102a','cc000000-0000-0000-0000-00000000000c','Current Affairs','Operation Kaveri in 2023 was conducted to evacuate Indians from:','Afghanistan','Sudan','Ukraine','Yemen','B','Operation Kaveri was launched by India to evacuate Indian nationals stranded in Sudan during the 2023 Sudanese conflict.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('a8fbd3e2-9645-416f-87b7-e1bdd6a45236','ce000000-0000-0000-0000-00000000000e','Quantitative Aptitude','The area of a circle with radius 7 cm is: (use π = 22/7)','154 sq cm','144 sq cm','164 sq cm','174 sq cm','A','Area = πr² = (22/7)×7×7 = 22×7 = 154 sq cm.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('34cd39b8-c1bf-415d-b169-8648001c71ff','ce000000-0000-0000-0000-00000000000e','Quantitative Aptitude','A number is increased by 20% and then decreased by 20%. The net change in the number is:','4% decrease','4% increase','No change','2% decrease','A','Net effect = (20×20)/100 = 4% decrease (since increase then decrease by same %).','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('05357694-86dd-4a46-bb93-5356fb3a1d4b','ce000000-0000-0000-0000-00000000000e','Quantitative Aptitude','If the perimeter of a square is 48 cm, its area is:','121 sq cm','144 sq cm','169 sq cm','100 sq cm','B','Side = 48/4 = 12 cm. Area = 12² = 144 sq cm.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('209ac7c3-705c-4642-9a49-7ec82fcb50fd','ce000000-0000-0000-0000-00000000000e','Reasoning','Select the related pair: Pen : Write :: Knife : ?','Cut','Sharp','Steel','Cook','A','Pen is used to write; Knife is used to cut. Functional relationship.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1a65bd7d-f6eb-4ac6-9aa6-09f6dc4790d2','ce000000-0000-0000-0000-00000000000e','Reasoning','If 4 x 3 = 24 and 6 x 5 = 60, then 8 x 7 = ?','96','112','56','105','B','Pattern: a x b = a × b × 2: 4×3×2=24, 6×5×2=60, 8×7×2=112.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('ec8a61e3-b047-47a4-a172-fb32bdba25cf','ce000000-0000-0000-0000-00000000000e','Reasoning','From the given options, which figure can be formed by folding the given net of a cube?','Option A','Option B','Option C','Option D','A','This is a standard cube net question. The correct cube is formed by option A based on typical TNPSC patterns.','medium',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('10999ca9-8187-4027-8def-c1389c268aee','ce000000-0000-0000-0000-00000000000e','English','Choose the correct meaning of the phrase ''AT THE DROP OF A HAT'':','Immediately, without hesitation','Very slowly','After careful thought','In a careless manner','A','''At the drop of a hat'' means without hesitation; immediately.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('b2093ac4-2ddc-4145-b42e-2273af0fdfae','ce000000-0000-0000-0000-00000000000e','English','Pick the correctly punctuated sentence:','She said ''I will come tomorrow''','She said, "I will come tomorrow."','She said, I will come tomorrow.','She said "I will come tomorrow"','B','Direct speech requires a comma before the quote and a period inside the closing quotation mark.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5e2df798-e094-45f8-b3fc-ee7dd619927d','ce000000-0000-0000-0000-00000000000e','English','The plural of ''crisis'' is:','Crisises','Crises','Crisis','Crisies','B','Words derived from Greek ending in -is form their plural by changing -is to -es: crisis → crises.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e3a2b46e-8069-4154-8762-8226913cb9f1','ce000000-0000-0000-0000-00000000000e','General Knowledge','Tamil Nadu is known as the ''Land of Temples''. Which temple is called ''Dakshina Meru''?','Madurai Meenakshi Temple','Brihadeeswarar Temple, Thanjavur','Nataraja Temple, Chidambaram','Shore Temple, Mahabalipuram','B','The Brihadeeswarar Temple in Thanjavur is called Dakshina Meru (Meru of the South) due to its towering vimana.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('d087f10b-0ef5-4293-9e5c-4e925edb833b','ce000000-0000-0000-0000-00000000000e','General Knowledge','Which river is called the ''Ganges of the South''?','Kaveri','Krishna','Godavari','Tungabhadra','C','Godavari is called the ''Ganges of the South'' due to its religious significance and length.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('37da982f-e27d-4d40-af45-7b0db1412176','ce000000-0000-0000-0000-00000000000e','General Knowledge','The state animal of Tamil Nadu is:','Tiger','Nilgiri Tahr','Elephant','Spotted Deer','B','The Nilgiri Tahr is the state animal of Tamil Nadu. It is found in the Nilgiri Hills.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('4b6659c6-3325-4ddd-9952-f6c6e4f54b28','ce000000-0000-0000-0000-00000000000e','Current Affairs','The ''Vanavil'' scheme in Tamil Nadu is related to:','Agricultural support','Rainbow colours — LGBTQ support','Welfare of disabled persons','Women safety','C','Vanavil scheme provides welfare assistance to persons with disabilities in Tamil Nadu.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('414dd29d-38de-41f3-b6a6-e3745ca4839e','ce000000-0000-0000-0000-00000000000e','Current Affairs','Which port in Tamil Nadu is being developed as a major transshipment hub?','Chennai Port','Tuticorin Port','Ennore Port','Colachel Port','D','Colachel (Vizhinjam) port project in Tamil Nadu''s southern tip is being developed as a major deep-sea transshipment hub.','hard',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('5f31d27f-848e-4410-8706-bfaf13c697fd','ce000000-0000-0000-0000-00000000000e','Current Affairs','The headquarters of Tamil Nadu Government is located in:','Madurai','Coimbatore','Chennai','Tiruchirapalli','C','Chennai (formerly Madras) is the capital city and headquarters of the Tamil Nadu Government.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('97afe62f-b129-4204-b457-9e6749eb0433','c9000000-0000-0000-0000-000000000009','Quantitative Aptitude','The value of sin30° + cos60° is:','0','1','√2','2','B','sin30° = 1/2 and cos60° = 1/2. So sin30° + cos60° = 1/2 + 1/2 = 1.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('13ca820e-4046-4ddc-b2df-8939ad7296c7','c9000000-0000-0000-0000-000000000009','Quantitative Aptitude','If a matrix A is of order 2×3 and matrix B is of order 3×4, then the order of AB is:','2×4','3×3','4×2','2×3','A','When multiplying A(m×n) × B(n×p), result is m×p. So (2×3)(3×4) = 2×4.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('d9807371-d882-46ff-84f9-b5ef5ceafd77','c9000000-0000-0000-0000-000000000009','Quantitative Aptitude','The eccentricity of a circle is:','0','1','Greater than 1','Between 0 and 1','A','A circle is a special case of an ellipse with eccentricity e=0 (both foci coincide at the center).','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('9f62a8c4-53ab-4126-b587-94a801792500','c9000000-0000-0000-0000-000000000009','General Knowledge','The first battle of Panipat (1526) was fought between:','Akbar and Hemu','Babur and Ibrahim Lodi','Humayun and Sher Shah Suri','Babur and Rana Sanga','B','The First Battle of Panipat on April 21, 1526 was between Babur and Ibrahim Lodi, establishing the Mughal Empire.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('4a96a9a6-3842-423b-b60d-5a1c378d5e8a','c9000000-0000-0000-0000-000000000009','General Knowledge','INS Vikrant, India''s first indigenous aircraft carrier, was commissioned in:','2021','2022','2023','2020','B','INS Vikrant was commissioned into the Indian Navy on September 2, 2022 by Prime Minister Narendra Modi.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('ace4f71a-e6e3-4afe-8a1a-7a3553e410a3','c9000000-0000-0000-0000-000000000009','General Knowledge','The Param Vir Chakra is awarded for:','Gallantry in the presence of the enemy','Distinguished service of a high order','Long distinguished service','Acts of courage not in the face of the enemy','A','Param Vir Chakra is India''s highest military decoration, awarded for conspicuous gallantry in the presence of the enemy.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e30581b9-f230-4d53-b7cc-2df94cbfa917','c9000000-0000-0000-0000-000000000009','Reasoning','A soldier walks 10 m towards South, turns left and walks 15 m, turns left again and walks 10 m. How far is he from the starting point?','10 m','15 m','5 m','25 m','B','10S, 15E, 10N → net: 0 N-S, 15 E. Distance from start = 15 m East.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1b02d441-72f2-45ce-aa18-1f3a34726e25','c9000000-0000-0000-0000-000000000009','Reasoning','If CADET is coded as 24895, how is TRADE coded?','59248','89245','59284','58924','A','C=2,A=4,D=8,E=9,T=5. TRADE: T=5,R=?,A=4,D=8,E=9. Since R is not in CADET, code is 5(R)489. Check answer A=59248.','hard',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('28af7a31-43c7-4540-9319-55299ef78872','c9000000-0000-0000-0000-000000000009','English','Choose the correct form: ''The soldiers _____ standing at attention.''','is','are','was','were','B','''Soldiers'' is plural, so the correct verb is ''are'' (present tense).','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('344584a2-eb21-4f82-8c81-1ea443f563d6','c9000000-0000-0000-0000-000000000009','English','Identify the type of sentence: ''What a brave soldier he is!''','Interrogative','Declarative','Exclamatory','Imperative','C','Sentences expressing strong emotion or surprise are exclamatory sentences, often ending with ''!''.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('f24d65c7-8933-4155-81de-d568c5f74805','c9000000-0000-0000-0000-000000000009','English','The synonym of VALIANT is:','Cowardly','Brave','Weak','Dishonest','B','Valiant means possessing or showing courage or determination. Its synonym is brave.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1ac8cc39-1e89-4d2f-aecb-1f5a91299f79','c9000000-0000-0000-0000-000000000009','Current Affairs','Exercise ''Tasman Saber'' is a bilateral military exercise between India and:','USA','Australia','Japan','France','B','Exercise Tasman Saber is a bilateral military exercise between the USA and Australia (India participates in other exercises).','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('6a8d8288-69a4-4326-972c-d51529195bae','c9000000-0000-0000-0000-000000000009','Current Affairs','AGNI-V missile is capable of carrying nuclear warheads to a range of approximately:','700 km','3500 km','5000 km','8000 km','C','Agni-V is an intercontinental ballistic missile with a strike range of approximately 5,000-5,500 km.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('58bb40b4-0a48-4e50-8bdc-56824f42691d','c9000000-0000-0000-0000-000000000009','Current Affairs','The first Chief of Defence Staff (CDS) of India was:','General Bipin Rawat','General Manoj Mukund Naravane','Air Chief Marshal R.K.S. Bhadauria','Admiral Karambir Singh','A','General Bipin Rawat was appointed as India''s first Chief of Defence Staff (CDS) on January 1, 2020.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e536af2c-3531-48c7-9cff-8a2aec1bc00a','c8000000-0000-0000-0000-000000000008','Quantitative Aptitude','A flagstaff 10 m high casts a shadow of 10/√3 m. What is the angle of elevation of the sun?','30°','45°','60°','75°','C','tan θ = height/shadow = 10/(10/√3) = √3. So θ = 60°.','medium',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('36e9aeef-acd7-42dc-814c-9df3cd9ebb1a','c8000000-0000-0000-0000-000000000008','Quantitative Aptitude','What is the number of diagonals of a hexagon?','6','9','12','15','B','Diagonals of n-polygon = n(n-3)/2 = 6(6-3)/2 = 6×3/2 = 9.','easy',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('4adc213b-069c-4de4-aacb-ed38c4a32813','c8000000-0000-0000-0000-000000000008','Quantitative Aptitude','If log(2) = 0.3010, the value of log(8) is:','0.6020','0.9030','1.2040','0.3010','B','log(8) = log(2³) = 3×log(2) = 3×0.3010 = 0.9030.','easy',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('f6471671-a68b-4b60-b09e-9ce7b30099fd','c8000000-0000-0000-0000-000000000008','General Knowledge','Operation Vijay (1999) was conducted to recapture peaks in:','Siachen Glacier','Aksai Chin','Kargil sector','Arunachal Pradesh','C','Operation Vijay was the Indian military operation to recapture positions in the Kargil sector occupied by Pakistani forces in 1999.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('de9ceb7f-a08f-409e-a900-2866f0833b28','c8000000-0000-0000-0000-000000000008','General Knowledge','The highest gallantry award equivalent to Param Vir Chakra given during peacetime is:','Ashoka Chakra','Kirti Chakra','Shaurya Chakra','Vir Chakra','A','Ashoka Chakra is India''s highest peacetime gallantry award, equivalent to Param Vir Chakra (wartime).','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e689b38a-625d-4394-a4cf-5a08bf050285','c8000000-0000-0000-0000-000000000008','General Knowledge','The Combined Defence Services Examination is conducted by:','Ministry of Defence','UPSC','Ministry of Home Affairs','Armed Forces','B','The Combined Defence Services (CDS) Examination is conducted twice a year by the Union Public Service Commission (UPSC).','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1f5a07e5-d114-463d-a029-c89b195f2c18','c8000000-0000-0000-0000-000000000008','Reasoning','5 officers take 10 days to complete a task. How many days will 10 officers take?','10 days','5 days','20 days','2 days','B','Work is inversely proportional to men. 5×10 = 10×x → x = 5 days.','easy',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('c185c40e-b653-482d-8db6-7b385326e29a','c8000000-0000-0000-0000-000000000008','Reasoning','Which number replaces ''?'' in: 4, 8, 24, 96, ?','288','384','480','192','C','Pattern: ×2, ×3, ×4, ×5... 4×2=8, 8×3=24, 24×4=96, 96×5=480.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('3c556196-fe0a-40f4-9c54-68f6aa4dfcdf','c8000000-0000-0000-0000-000000000008','Reasoning','Six people A, B, C, D, E, F sit in a row. B is next to A, D is not next to C, F is at one end. Which arrangement is possible?','FABCDE','FABCDE','FABCDE','EABCDF','A','Standard seating puzzle — FABCDE satisfies all conditions: F at end, B next to A, D not next to C.','hard',2020,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('72a06dd6-76cb-4070-ab88-3a2b9caf83c2','c8000000-0000-0000-0000-000000000008','English','Choose the correctly punctuated option: The soldier said _____ I will defend my country to the last_____.','The soldier said, ''I will defend my country to the last.''','The soldier said ''I will defend my country to the last''','The soldier said; I will defend my country to the last.','The soldier said: I will defend my country to the last','A','Direct speech uses a comma after the reporting verb and quotes around the spoken words, with a period inside the quote.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('1bb614e9-b31b-44da-af09-c3b8db5f550b','c8000000-0000-0000-0000-000000000008','English','The word ''Sortie'' in military language means:','An attack by troops from a besieged place','A type of weapon','Military uniform','A naval maneuver','A','Sortie refers to an attack made by troops coming out from a position of defense; it also refers to an operational flight by a single military aircraft.','hard',2022,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('e03b8f3c-5242-45f3-a671-e80ee8cbcdf9','c8000000-0000-0000-0000-000000000008','English','Select the correct indirect speech: He said, ''I am reading the map.''','He said that he was reading the map.','He said that I am reading the map.','He told that he is reading the map.','He said that he has been reading the map.','A','In indirect speech, ''I'' changes to ''he'', present continuous changes to past continuous.','medium',2021,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('de844409-3e6b-4ab6-918c-11675ec7a5ad','c8000000-0000-0000-0000-000000000008','Current Affairs','Exercise ''Tarkash'' is a joint military exercise between India and:','Russia','France','Israel','USA','B','Exercise Tarkash is a joint military exercise conducted between India and France.','medium',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('df346a11-63b9-4e73-a591-cf083034153b','c8000000-0000-0000-0000-000000000008','Current Affairs','India''s Light Combat Aircraft (LCA) Tejas is manufactured by:','DRDO','HAL','BEL','BEML','B','HAL (Hindustan Aeronautics Limited) manufactures the LCA Tejas fighter aircraft, designed by DRDO''s ADA.','easy',2023,TRUE) ON CONFLICT DO NOTHING;
INSERT INTO questions(id,exam_id,topic,question_text,option_a,option_b,option_c,option_d,correct_ans,explanation,difficulty,year,is_demo) VALUES('b0bb9f41-fe3a-48be-a693-0b3b205f1212','c8000000-0000-0000-0000-000000000008','Current Affairs','INS Mormugao, inducted in December 2022, belongs to which class of destroyer?','Delhi class','Kolkata class','Visakhapatnam class','Rajput class','C','INS Mormugao is a Visakhapatnam-class guided-missile destroyer commissioned into the Indian Navy in December 2022.','hard',2022,TRUE) ON CONFLICT DO NOTHING;
